user.source:
/// A person the survey is about.
type User = {
  id:string
  /// What to call them.
  name:string?
}

guardedStep.source:
type Step = { title:string }

let steps(step:int, role:string) = {
  if step == 3 && role != "engineer" { <Step title="Reports" /> }
}

operators.source:
let sum(a:int, b:int) = { (a + b) * 2 - a / b }
let rest(a:int, b:int) = { a % b }
let compare(a:int, b:int) = { a <= b || a >= b && !(a < b) }
let given(s:string?) = { s? }
let negative(a:int) = { -a }
let upTo(a:int) = { 1..a }
let through(a:int) = { 1..=a }

logic.source:
type Shape = circle | square

let describe(shape:Shape) = {
  if shape is {
    circle => "round"
    else => "angular"
  }
}

let doubled(items:int*) = {
  for item in items { item * 2 }
}

